const handWrittenFixture = `package flexera

// WidgetOption configures a Widget.
type WidgetOption func(*widget)

type widget struct{ name string }

// NewWidget builds a Widget with the given options.
//
// Additional doc lines should not appear in the manifest.
func NewWidget(opts ...WidgetOption) *widget { return &widget{} }

func (w *widget) unexported() {}

// Version is the current widget schema version.
const Version = 1
`

func TestRunSplitsByNamespaceAndConcern(t *testing.T) {
	dir := t.TempDir()
	input := filepath.Join(dir, "client.gen.tmp.go")
	spec := filepath.Join(dir, "openapi.json")
	config := filepath.Join(dir, "specs.yaml")
	writeTestFile(t, input, generatedFixture)
	writeTestFile(t, spec, `{"openapi":"3.0.3","servers":[{"url":"https://api.flexera.{zone}"}]}`)
	writeTestFile(t, config, "specs:\n  - id: flexera-budget-v1\n    vendor: flexera\n    service: budget\n")
	writeTestFile(t, filepath.Join(dir, "client_gen_stale.go"), "package flexera\n")
	writeTestFile(t, filepath.Join(dir, "widget.go"), handWrittenFixture)

	if err := run(options{input: input, outputDir: dir, spec: spec, specConfig: config}); err != nil {
		t.Fatal(err)
	}

	for _, name := range []string{
		"client_gen_core.go",
		"client_gen_budget_models.go",
		"client_gen_budget_operations.go",
		"client_gen_budget_responses.go",
		"client_gen_optima_routing.go",
		manifestName,
		extensionsName,
	} {
		if _, err := os.Stat(filepath.Join(dir, name)); err != nil {
			t.Errorf("%s was not generated: %v", name, err)
		}
	}
	if _, err := os.Stat(filepath.Join(dir, "client_gen_stale.go")); !os.IsNotExist(err) {
		t.Fatalf("stale generated file was not removed")
	}

	operations := readTestFile(t, filepath.Join(dir, "client_gen_budget_operations.go"))
	if !strings.Contains(operations, "func (c *Client) BudgetList") || !strings.Contains(operations, "type BudgetListParams") {
		t.Fatalf("operation declarations were not grouped together:\n%s", operations)
	}
	if strings.Contains(operations, `"encoding/json"`) {
		t.Fatalf("unused import was retained:\n%s", operations)
	}

	responses := readTestFile(t, filepath.Join(dir, "client_gen_budget_responses.go"))
	if !strings.Contains(responses, "ParseBudgetListResponse") || !strings.Contains(responses, `"encoding/json"`) {
		t.Fatalf("response declarations or imports were not preserved:\n%s", responses)
	}
	models := readTestFile(t, filepath.Join(dir, "client_gen_budget_models.go"))
	if !strings.Contains(models, "const Active BudgetThingState") {
		t.Fatalf("typed enum constant was not assigned to its model namespace:\n%s", models)
	}
	core := readTestFile(t, filepath.Join(dir, "client_gen_core.go"))
	if strings.Contains(core, "BudgetThingState") {
		t.Fatalf("service-specific declaration leaked into core:\n%s", core)
	}
	routing := readTestFile(t, filepath.Join(dir, "client_gen_optima_routing.go"))
	if !strings.Contains(routing, "var optimaHostedPathPrefixes = []string{}") {
		t.Fatalf("expected no Optima-hosted prefixes for a spec with no servers overrides:\n%s", routing)
	}

	var got manifest
	data, err := os.ReadFile(filepath.Join(dir, manifestName))
	if err != nil {
		t.Fatal(err)
	}
	if err := json.Unmarshal(data, &got); err != nil {
		t.Fatal(err)
	}
	if got.Generator != "test-generator v1.2.3" || got.TotalFiles != 5 {
		t.Fatalf("unexpected manifest: %#v", got)
	}
	if got.Source != "openapi.json" {
		t.Fatalf("manifest source is not relative: %q", got.Source)
	}
	for _, file := range got.Files {
		content, err := os.ReadFile(filepath.Join(dir, file.Path))
		if err != nil {
			t.Fatal(err)
		}
		if want := fmt.Sprintf("%x", sha256.Sum256(content)); file.SHA256 != want {
			t.Fatalf("manifest file %q has SHA-256 %q, want %q", file.Path, file.SHA256, want)
		}
	}

	var gotExtensions extensionsManifest
	extensionsData, err := os.ReadFile(filepath.Join(dir, extensionsName))
	if err != nil {
		t.Fatal(err)
	}
	if err := json.Unmarshal(extensionsData, &gotExtensions); err != nil {
		t.Fatal(err)
	}
	if gotExtensions.TotalFiles != 1 || len(gotExtensions.Files) != 1 {
		t.Fatalf("expected exactly one hand-written file in extensions manifest, got %#v", gotExtensions)
	}
	widgetFile := gotExtensions.Files[0]
	if widgetFile.Path != "widget.go" {
		t.Fatalf("unexpected extensions manifest file: %#v", widgetFile)
	}
	wantDecls := map[string]extensionsDeclaration{
		"WidgetOption": {Name: "WidgetOption", Kind: "type", Doc: "WidgetOption configures a Widget."},
		"NewWidget":    {Name: "NewWidget", Kind: "func", Doc: "NewWidget builds a Widget with the given options."},
		"Version":      {Name: "Version", Kind: "const", Doc: "Version is the current widget schema version."},
	}
	if len(widgetFile.Declarations) != len(wantDecls) {
		t.Fatalf("unexpected declarations: %#v", widgetFile.Declarations)
	}
	for _, decl := range widgetFile.Declarations {
		want, ok := wantDecls[decl.Name]
		if !ok {
			t.Fatalf("unexpected declaration %q in extensions manifest", decl.Name)
		}
		if decl != want {
			t.Fatalf("declaration %q = %#v, want %#v", decl.Name, decl, want)
		}
	}
	// widget (the unexported type) and its unexported method must not leak in.
	for _, decl := range widgetFile.Declarations {
		if decl.Name == "widget" || decl.Name == "unexported" {
			t.Fatalf("unexported declaration %q leaked into extensions manifest", decl.Name)
		}
	}
}

func TestHasGeneratedHeader(t *testing.T) {
	cases := []struct {
		name   string
		source string
		want   bool
	}{
		{"generated", "// Code generated by oapi-codegen version v2.5.0 DO NOT EDIT.\npackage flexera\n", true},
		{"generated with doc comment first", "// Package flexera is generated.\n// Code generated by test-generator v1.2.3 DO NOT EDIT.\npackage flexera\n", true},
		{"hand-written", "package flexera\n\n// WithHeaders adds static headers.\nfunc WithHeaders() {}\n", false},
		{"mentions DO NOT EDIT without marker", "// Please DO NOT EDIT this by hand, ask a human first.\npackage flexera\n", false},
	}
	for _, tc := range cases {
		t.Run(tc.name, func(t *testing.T) {
			if got := hasGeneratedHeader([]byte(tc.source)); got != tc.want {
				t.Fatalf("hasGeneratedHeader() = %v, want %v", got, tc.want)
			}
		})
	}
}

func TestComputeExtensionsManifestSkipsGeneratedAndTestFiles(t *testing.T) {
	dir := t.TempDir()
	writeTestFile(t, filepath.Join(dir, "widget.go"), handWrittenFixture)
	writeTestFile(t, filepath.Join(dir, "widget_test.go"), "package flexera\n\nfunc TestSomething() {}\n")
	writeTestFile(t, filepath.Join(dir, "client_gen_core.go"),
		"// Code generated by oapi-codegen version v2.5.0. DO NOT EDIT.\npackage flexera\n\n// Client is generated.\ntype Client struct{}\n")

	got, err := computeExtensionsManifest(dir, "flexera")
	if err != nil {
		t.Fatal(err)
	}
	if got.TotalFiles != 1 || got.Files[0].Path != "widget.go" {
		t.Fatalf("expected only widget.go to be inventoried, got %#v", got)
	}
}

func TestRunIsDeterministic(t *testing.T) {
	dir := t.TempDir()
	input := filepath.Join(dir, "generated.tmp.go")
	spec := filepath.Join(dir, "openapi.json")
	config := filepath.Join(dir, "specs.yaml")
	writeTestFile(t, input, generatedFixture)
	writeTestFile(t, spec, `{"servers":[{"url":"https://api.flexera.{zone}"}]}`)
	writeTestFile(t, config, "specs:\n  - id: flexera-budget-v1\n    vendor: flexera\n    service: budget\n")

	opts := options{input: input, outputDir: dir, spec: spec, specConfig: config}
	if err := run(opts); err != nil {
		t.Fatal(err)
	}
	first := snapshotOutputs(t, dir)
	if err := run(opts); err != nil {
		t.Fatal(err)
	}
	second := snapshotOutputs(t, dir)
	if first != second {
		t.Fatal("second generation changed split output")
	}
}

func TestLoadNamespacesRejectsCollisions(t *testing.T) {
	path := filepath.Join(t.TempDir(), "specs.yaml")
	writeTestFile(t, path, `specs:
  - id: first
    vendor: flexera
    service: billing-center
  - id: second
    vendor: flexera
    service: billing_center
`)
	if _, err := loadNamespaces(path); err == nil {
		t.Fatal("expected namespace collision error")
	}
}

func TestSplitFileRejectsUnknownDeclarations(t *testing.T) {
	dir := t.TempDir()
	input := filepath.Join(dir, "client.gen.tmp.go")
	writeTestFile(t, input, "package flexera\n\ntype UnexpectedGeneratedType struct{}\n")

	namespaces := []namespace{{Name: "Budget", FileSlug: "budget", SpecID: "flexera-budget-v1"}}
	if _, _, _, err := splitFile(input, namespaces); err == nil || !strings.Contains(err.Error(), "UnexpectedGeneratedType") {
		t.Fatalf("expected unknown declaration error, got %v", err)
	}
}

func TestMatchNamespaceRequiresIdentifierBoundary(t *testing.T) {
	namespaces := []namespace{{Name: "Cred", FileSlug: "cred", SpecID: "flexera-cred-v2"}}
	if _, ok := matchNamespace("CredentialsExportReport", namespaces); ok {
		t.Fatal("matched a namespace that was only a lowercase string prefix")
	}
	if got, ok := matchNamespace("CredCredentialIndex", namespaces); !ok || got.Name != "Cred" {
		t.Fatalf("did not match a valid namespace boundary: %#v, %v", got, ok)
	}
}

func TestVerifyDeclarationInventoryRejectsDroppedOrChangedDeclarations(t *testing.T) {
	source := map[string]string{"type:Example": "original"}
	if err := verifyDeclarationInventory(source, map[string]string{}); err == nil || !strings.Contains(err.Error(), "dropped") {
		t.Fatalf("expected dropped declaration error, got %v", err)
	}
	if err := verifyDeclarationInventory(source, map[string]string{"type:Example": "changed"}); err == nil || !strings.Contains(err.Error(), "changed") {
		t.Fatalf("expected changed declaration error, got %v", err)
	}
	if err := verifyDeclarationInventory(source, map[string]string{"type:Example": "original", "func:.Extra": "new"}); err == nil || !strings.Contains(err.Error(), "introduced") {
		t.Fatalf("expected introduced declaration error, got %v", err)
	}
}

func TestDeclarationInventoryIncludesComments(t *testing.T) {
	withOriginalComment := parseTestDeclarations(t, "// Example is documented.\ntype Example struct{}\n")
	withChangedComment := parseTestDeclarations(t, "// Example has changed documentation.\ntype Example struct{}\n")

	original, err := declarationInventory(withOriginalComment)
	if err != nil {
		t.Fatal(err)
	}
	changed, err := declarationInventory(withChangedComment)
	if err != nil {
		t.Fatal(err)
	}
	if err := verifyDeclarationInventory(original, changed); err == nil || !strings.Contains(err.Error(), "changed") {
		t.Fatalf("expected changed comment to fail inventory verification, got %v", err)
	}
}

func parseTestDeclarations(t *testing.T, declarations string) []ast.Decl {
	t.Helper()
	file, err := parser.ParseFile(token.NewFileSet(), "fixture.go", "package fixture\n\n"+declarations, parser.ParseComments)
	if err != nil {
		t.Fatal(err)
	}
	return file.Decls
}

func writeTestFile(t *testing.T, path, content string) {
	t.Helper()
	if err := os.WriteFile(path, []byte(content), 0o644); err != nil {
		t.Fatal(err)
	}
}

func readTestFile(t *testing.T, path string) string {
	t.Helper()
	data, err := os.ReadFile(path)
	if err != nil {
		t.Fatal(err)
	}
	return string(data)
}

func snapshotOutputs(t *testing.T, dir string) string {
	t.Helper()
	entries, err := filepath.Glob(filepath.Join(dir, "client_gen_*"))
	if err != nil {
		t.Fatal(err)
	}
	var result strings.Builder
	for _, path := range entries {
		data, err := os.ReadFile(path)
		if err != nil {
			t.Fatal(err)
		}
		result.WriteString(filepath.Base(path))
		result.Write(data)
	}
	return result.String()
}

func TestComputeOptimaHostedPrefixes_DerivesConsistentOverrides(t *testing.T) {
	spec := []byte(`{
		"servers": [{"url": "https://api.flexera.{zone}"}],
		"paths": {
			"/bill-analysis/orgs/{orgId}/adjustments": {
				"servers": [{"url": "https://api.optima{zone}.flexeraeng.com/bill-analysis"}]
			},
			"/bill-analysis/orgs/{orgId}/bill-months": {
				"servers": [{"url": "https://api.optima{zone}.flexeraeng.com/bill-analysis"}]
			},
			"/optima/orgs/{orgId}/billUploads": {
				"servers": [{"url": "https://api.optima{zone}.flexeraeng.com"}]
			},
			"/iam/v1/orgs/{orgId}": {},
			"/recommendation/v1/orgs/{orgId}/misconfiguration/list": {}
		}
	}`)
	got, err := computeOptimaHostedPrefixes(spec)
	if err != nil {
		t.Fatal(err)
	}
	want := []string{"/bill-analysis", "/optima"}
	if len(got) != len(want) {
		t.Fatalf("got %v, want %v", got, want)
	}
	for i := range want {
		if got[i] != want[i] {
			t.Fatalf("got %v, want %v", got, want)
		}
	}
}

func TestComputeOptimaHostedPrefixes_ErrorsOnPartialCoverage(t *testing.T) {
	spec := []byte(`{
		"servers": [{"url": "https://api.flexera.{zone}"}],
		"paths": {
			"/bill-analysis/orgs/{orgId}/adjustments": {
				"servers": [{"url": "https://api.optima{zone}.flexeraeng.com/bill-analysis"}]
			},
			"/bill-analysis/orgs/{orgId}/bill-months": {}
		}
	}`)
	if _, err := computeOptimaHostedPrefixes(spec); err == nil {
		t.Fatal("expected an error for inconsistent (partial) servers-override coverage under one prefix")
	}
}

func TestComputeOptimaHostedPrefixes_ErrorsOnConflictingHosts(t *testing.T) {
	spec := []byte(`{
		"servers": [{"url": "https://api.flexera.{zone}"}],
		"paths": {
			"/bill-analysis/orgs/{orgId}/adjustments": {
				"servers": [{"url": "https://api.optima{zone}.flexeraeng.com"}]
			},
			"/bill-analysis/orgs/{orgId}/bill-months": {
				"servers": [{"url": "https://api.other-host.flexeraeng.com"}]
			}
		}
	}`)
	if _, err := computeOptimaHostedPrefixes(spec); err == nil {
		t.Fatal("expected an error for a prefix whose paths disagree on override host")
	}
}

func TestComputeOptimaHostedPrefixes_IgnoresOperationLevelOverrides(t *testing.T) {
	// The /oidc/token login override is operation-level, not path-item
	// level, and must NOT be picked up here: it's handled separately by
	// AuthHelper, which never goes through the generated *Client's HTTP
	// doer.
	spec := []byte(`{
		"servers": [{"url": "https://api.flexera.{zone}"}],
		"paths": {
			"/oidc/token": {
				"post": {
					"servers": [{"url": "https://login.flexera.{zone}"}]
				}
			}
		}
	}`)
	got, err := computeOptimaHostedPrefixes(spec)
	if err != nil {
		t.Fatal(err)
	}
	if len(got) != 0 {
		t.Fatalf("expected no prefixes derived from an operation-level override, got %v", got)
	}
}
